import{_ as e,o,c as d,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-PCOMPUTE.md","filePath":"manual-en/CTABLES-PCOMPUTE.md","lastUpdated":1785684581000}'),r={name:"manual-en/CTABLES-PCOMPUTE.md"};function s(i,t,c,n,p,m){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-10-1-pcompute" tabindex="-1">15.7.10.1 PCOMPUTE <a class="header-anchor" href="#_15-7-10-1-pcompute" aria-label="Permalink to &quot;15.7.10.1 PCOMPUTE&quot;">​</a></h4><pre><code>/PCOMPUTE &amp;_postcompute_ =EXPR(_expression_)
</code></pre><p>The <code>PCOMPUTE</code> subcommand, which must precede the first <code>TABLE</code> command, defines computed categories. It is optional and may be used any number of times to define multiple postcomputes.</p><p>Each <code>PCOMPUTE</code> defines one postcompute. Its syntax consists of a name to identify the postcompute as a PSPP identifier prefixed by ‘&amp;’, followed by ‘=’ and a postcompute expression enclosed in <code>EXPR(…)</code>. A postcompute expression consists of:</p><p><code>[_category_]</code></p><p>This form evaluates to the summary statistic for <em>category</em> , e.g. <code>[1]</code> evaluates to the value of the summary statistic associated with category 1. The <em>category</em> may be a number, a quoted string, or a quoted time or date value. All of the categories for a given postcompute must have the same form. The category must appear in all the <code>CATEGORIES</code> list in which the postcompute is used.</p><p><code>[_min_ THRU _max_]</code><code>[LO THRU _max_]</code><code>[_min_ THRU HI]</code><code>MISSING</code><code>OTHERNM</code></p><p>These forms evaluate to the summary statistics for a category specified with the same syntax, as described in previous section (see <a href="./CTABLES-Explicit-Categories#CTABLES-Explicit-Category-List">CTABLES Explicit Category List</a>). The category must appear in all the <code>CATEGORIES</code> list in which the postcompute is used.</p><p><code>SUBTOTAL</code></p><p>The summary statistic for the subtotal category. This form is allowed only if the <code>CATEGORIES</code> lists that include this postcompute have exactly one subtotal.</p><p><code>SUBTOTAL[_index_]</code></p><p>The summary statistic for subtotal category <em>index</em> , where 1 is the first subtotal, 2 is the second, and so on. This form may be used for <code>CATEGORIES</code> lists with any number of subtotals.</p><p><code>TOTAL</code></p><p>The summary statistic for the total. The <code>CATEGORIES</code> lsits that include this postcompute must have a total enabled.</p><p><code>_a_ + _b_</code><code>_a_ - _b_</code><code>_a_ * _b_</code><code>_a_ / _b_</code><code>_a_ ** _b_</code></p><p>These forms perform arithmetic on the values of postcompute expressions <em>a</em> and <em>b</em>. The usual operator precedence rules apply.</p><p><code>_number_</code></p><p>Numeric constants may be used in postcompute expressions.</p><p><code>(_a_)</code></p><p>Parentheses override operator precedence.</p><p>A postcompute is not associated with any particular variable. Instead, it may be referenced within <code>CATEGORIES</code> for any suitable variable (e.g. only a string variable is suitable for a postcompute expression that refers to a string category, only a variable with subtotals for an expression that refers to subtotals, …).</p><p>Normally a named postcompute is defined only once, but if a later <code>PCOMPUTE</code> redefines a postcompute with the same name as an earlier one, the later one take precedence.</p><p>The following syntax and output shows how <code>PCOMPUTE</code> can compute a total over subtotals, summing the “Frequent Drivers” and “Infrequent Drivers” subtotals to form an “All Drivers” postcompute. It also shows how to calculate and display a percentage, in this case the percentage of valid responses that report never driving. It uses <code>PPROPERTIES</code> (see <a href="./CTABLES-PPROPERTIES">CTABLES PPROPERTIES</a>) to display the latter in <code>PCT</code> format.</p><pre><code>CTABLES
    /PCOMPUTE &amp;all_drivers=EXPR([1 THRU 2] + [3 THRU 4])
    /PPROPERTIES &amp;all_drivers LABEL=&#39;All Drivers&#39;
    /PCOMPUTE &amp;pct_never=EXPR([5] / ([1 THRU 2] + [3 THRU 4] + [5]) * 100)
    /PPROPERTIES &amp;pct_never LABEL=&#39;% Not Drivers&#39; FORMAT=COUNT PCT40.1
    /TABLE=freqOfDriving BY gender
    /CATEGORIES VARIABLES=freqOfDriving
                             [1 THRU 2, SUBTOTAL=&#39;Frequent Drivers&#39;,
                              3 THRU 4, SUBTOTAL=&#39;Infrequent Drivers&#39;,
                              &amp;all_drivers, 5, &amp;pct_never,
                              MISSING, SUBTOTAL=&#39;Not Drivers or Missing&#39;].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>2305</td><td>2362</td></tr><tr><td>Several days a week</td><td>440</td><td>834</td><td></td></tr><tr><td>Frequent Drivers</td><td>2745</td><td>3196</td><td></td></tr><tr><td>Once a week or less</td><td>125</td><td>236</td><td></td></tr><tr><td>Only certain times a year</td><td>58</td><td>72</td><td></td></tr><tr><td>Infrequent Drivers</td><td>183</td><td>308</td><td></td></tr><tr><td>All Drivers</td><td>2928</td><td>3504</td><td></td></tr><tr><td>Never</td><td>192</td><td>348</td><td></td></tr><tr><td>% Not Drivers</td><td>6.2%</td><td>9.0%</td><td></td></tr><tr><td>Don&#39;t know</td><td>3</td><td>5</td><td></td></tr><tr><td>Refused</td><td>9</td><td>10</td><td></td></tr><tr><td>Not Drivers or Missing</td><td>204</td><td>363</td><td></td></tr></tbody></table>`,25)])])}const h=e(r,[["render",s]]);export{u as __pageData,h as default};
